{
  "focus_areas": [
    "LDL cholesterol",
    "Triglycerides",
    "Heart-healthy Indian meals",
    "Gentle activity only as advised by doctor"
  ],
  "diet_recommendations": [
    {
      "item": "Breakfast within 1 hour of waking: 40 g dry oats cooked in water or skimmed milk with 1 small guava or apple, 5 days a week; on other days have 2 ragi idlis with 1 katori sambar.",
      "rationale": "Oats and ragi provide soluble fibre that helps lower LDL cholesterol; whole fruit adds fibre without sweetened drinks.",
      "linked_biomarker": "ldl"
    },
    {
      "item": "Lunch before 2 pm: 1 cup cooked bajra, jowar or ragi (or brown rice) with 1 katori dal, 2 katoris seasonal sabzi and 1 bowl salad.",
      "rationale": "Whole millets and dal give fibre and slowly digested carbohydrates, helping lower triglycerides when they replace refined grains.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "Mid-morning or evening snack: 1 small katori (about 30 g) sprouted moong or chana salad, or roasted chana, instead of biscuits or fried snacks.",
      "rationale": "Sprouts and chana are high-fibre protein foods that improve fullness and support lower LDL cholesterol.",
      "linked_biomarker": "ldl"
    },
    {
      "item": "Dinner before 8 pm: 1 katori dal or rajma/chana 3-4 days a week with 1-2 phulka without ghee and 2 katoris cooked vegetables; include grilled or baked fish 100-150 g 2 times a week instead of fried or fatty meat.",
      "rationale": "High-fibre legumes and fish in place of fried or fatty meats help lower triglycerides and support heart health.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "Cook with a measured total of 3 teaspoons (15 ml) oil per day for your portion; use mustard, groundnut or rice bran oil and do not reuse deep-frying oil.",
      "rationale": "Limiting added oil reduces excess calories and helps reduce triglycerides.",
      "linked_biomarker": "triglycerides"
    }
  ],
  "foods_to_avoid": [
    "Deep-fried foods such as samosa, pakora, puri and fried chicken",
    "Sweets, jaggery, honey, sugary drinks, fruit juices and bakery items",
    "Refined flour (maida) products such as white bread, naan, biscuits and cakes",
    "Processed and fatty meats such as sausage, salami, bacon and fatty red meat",
    "Butter, ghee, cream and full-fat dairy in large amounts",
    "Reusing deep-frying oil"
  ],
  "activity": "Follow your doctor's advice strictly: avoid strenuous exercise pending cardiology review. Do only gentle activity, such as a 15-20 minute easy walk at a comfortable pace after meals, 5 days a week if your doctor agrees. Stop immediately if you feel chest pain, breathlessness, dizziness or unusual tiredness.",
  "sleep": "Aim for 7-8 hours of sleep nightly. Keep a regular sleep schedule, avoid screens 1 hour before bed, and finish dinner at least 2-3 hours before lying down.",
  "retest_in_weeks": 12
}
